// Same arithmetic as the API follow-up, using the source coordinates directly.
export function followUpMetric(p){const w=p.football.record.width,n=w.defender_lateral_displacement_m.toFixed(1),eq=`|${w.defender_end_m[1].toFixed(1)} − ${w.defender_start_m[1].toFixed(1)}| = ${n} m`;return{value:n+' m',text:({en:`${eq}. This is lateral displacement, not total distance run or the winger’s causal effect.`,es:`${eq}. Es desplazamiento lateral, no distancia total ni efecto causal del extremo.`,pt:`${eq}. É deslocamento lateral, não distância total nem efeito causal do ponta.`})[p.language]};}
